qc = QuantumCircuit(20, 20)

for i in range(20):
    qc.rx(0.1, i)

for i in range(20):
    qc.ry(0.2, i)

for i in range(20):
    qc.rz(0.3, i)

for i in range(19):
    qc.cx(i, i+1)

qc.measure(range(20), range(20))

secret_string = "101"
n = len(secret_string)

qc = QuantumCircuit(n + 1, n)

qc.x(n)
qc.h(n)

for i in range(n):
    qc.h(i)

for i, bit in enumerate(reversed(secret_string)):
    if bit == '1':
        qc.cx(i, n)

for i in range(n):
    qc.h(i)

qc.measure(range(n), range(n))
